{
  "description": "The creature is a quadrupedal mammal shown in right-facing profile standing on a plain light background. Its body, head, and limbs are covered in long, shaggy brown fur that is darker on the legs and lighter on the muzzle and underside. The head is broad and bear-like with a blunt snout. A large, glossy, dark brown domed shell covers the entire back from the base of the neck to the rump, giving the dorsal side a hard, beetle-like appearance. The animal stands on four thick legs ending in clawed paws and has a small furry tail visible at the rear beneath the shell.",
  "parts": [
    {
      "part": "head",
      "looks_like": "broad, bear-like head with a blunt snout, black nose, closed mouth, dark eyes, and light brown fur on the muzzle darkening toward the neck",
      "where": "at the front of the body, facing to the right in profile"
    },
    {
      "part": "horns",
      "looks_like": "two dark gray to black pointed horns with a smooth surface; a large, long, backward-curving horn on the tip of the snout and a much smaller, short, conical horn on the forehead between the eyes",
      "where": "on the front of the head, one on the nose tip and one on the mid-forehead"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, densely furred ears with brown fur",
      "where": "on the top of the head, one more forward and one slightly behind"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar, heavily furred legs covered in long shaggy dark brown fur",
      "where": "supporting the body, two forelegs under the chest and two hindlegs under the rear"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with visible pale, curved claws on the toes",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a small, short, furry tuft of dark brown fur",
      "where": "at the extreme rear of the body, protruding slightly from under the back edge of the shell on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "a large, glossy, dark brown domed hard covering with a smooth reflective surface; the posterior portion shows fine parallel ridged lines",
      "where": "covering the entire dorsal side from the back of the neck to the rump, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "the shell is divided into two main domed plates with a distinct seam between them and a border of small rectangular segmented plates along the lower rim",
      "where": "the anterior plate over the shoulders and the larger posterior plate over the back and rump, with the segmented rim encircling the bottom edge of the shell"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
